// Stop early with a clear message if Settings still holds the template placeholders.
{
  const s = $('Settings').first().json;
  const unset = ["myAddress", "companyName", "signature", "generalEmail"].filter(k => !String(s[k] ?? '').trim() || String(s[k]).includes('REPLACE_ME'));
  if (unset.length) {
    throw new Error('Open the Settings node and fill in: ' + unset.join(', ') + '. They still contain REPLACE_ME placeholders.');
  }
}

// Normalize each Gmail message and flag automated or bulk mail, so we never spend an AI call on it.
return $input.all().map(item => {
  const m = item.json;
  const headers = m.headers || {};
  const h = key => String(headers[key] || '').toLowerCase();

  const sender = (m.from && m.from.value && m.from.value[0]) || {};
  const fromAddr = String(sender.address || '').toLowerCase();
  const fromName = sender.name || '';
  const subject = m.subject || '';
  const body = String(m.text || '').replace(/\s+/g, ' ').trim().slice(0, 6000);

  const automatedSender = /(no-?reply|do-?not-?reply|mailer-daemon|postmaster|notifications?@|newsletter|bounce)/i.test(fromAddr);
  const autoSubmitted = h('auto-submitted');
  const bulkHeaders =
    Boolean(headers['list-unsubscribe']) ||
    /(bulk|list|junk)/.test(h('precedence')) ||
    (autoSubmitted !== '' && !/(^|:\s*)no\s*$/.test(autoSubmitted));
  // Follow-ups in an existing ticket thread are routed again, but never re-acknowledged.
  const isReply = /^\s*(re|fwd?|aw)\s*:/i.test(subject);
  const isSelf = fromAddr === String(m.myAddress || '').toLowerCase();

  let skipReason = '';
  if (isSelf) skipReason = 'sent by me';
  else if (automatedSender) skipReason = 'automated sender';
  else if (bulkHeaders) skipReason = 'bulk or mailing-list headers';

  return {
    json: {
      messageId: m.id,
      threadId: m.threadId,
      // Stable per Gmail thread, so follow-ups keep the same ticket number.
      ticketRef: 'T-' + String(m.threadId || m.id || '').slice(-6).toUpperCase(),
      fromAddr,
      fromName,
      firstName: fromName.split(/\s+/)[0] || '',
      subject,
      body,
      isReply,
      skipReason,
    },
  };
});

// Pick the person for each ticket and write the notification and acknowledgement texts.
const s = $('Settings').first().json;
const teamEmail = {
  billing: s.billingEmail,
  technical: s.technicalEmail,
  account: s.accountEmail,
  sales: s.salesEmail,
  general: s.generalEmail,
};

return $input.all().map((item, i) => {
  const t = $('Prepare Ticket').itemMatching(i).json;
  const ai = item.json.output;
  const team = ai.team || 'general';
  const assignee = String(teamEmail[team] || '').trim() || s.generalEmail;
  const urgent = ai.priority === 'urgent';
  const route = !ai.is_support || ai.is_spam ? 'ignore' : urgent ? 'urgent' : 'normal';
  const responseTime = urgent ? s.urgentResponseTime : s.normalResponseTime;

  const notifySubject = `${urgent ? '[URGENT] ' : ''}[${t.ticketRef}] ${team}, ${ai.priority}: ${t.subject}`;
  const notifyBody = [
    `${urgent ? 'URGENT ticket' : 'New ticket'} ${t.ticketRef}${t.isReply ? ' (follow-up in an existing thread)' : ''}`,
    '',
    `From: ${t.fromName} <${t.fromAddr}>`,
    `Subject: ${t.subject}`,
    `Team: ${team}   Priority: ${ai.priority}   Sentiment: ${ai.sentiment}`,
    ai.customer_ref ? `Reference: ${ai.customer_ref}` : '',
    '',
    `Summary: ${ai.summary}`,
    `Why: ${ai.reason}`,
    '',
    `Open in Gmail (support inbox): https://mail.google.com/mail/u/0/#all/${t.threadId}`,
    '',
    '---- Original message ----',
    t.body,
  ].filter((line, n, all) => line !== '' || all[n - 1] !== '').join('\n');

  const ackMessage = [
    `Hi ${t.firstName || 'there'},`,
    '',
    `Thanks for contacting ${s.companyName}. We've received your message about ${ai.topic || 'your request'} and logged it as ticket ${t.ticketRef}.`,
    '',
    `${urgent ? "We've marked it as urgent, and " : ''}${urgent ? 's' : 'S'}omeone from our team will get back to you within ${responseTime}. If you have anything to add, just reply to this email.`,
    '',
    'Best regards,',
    s.signature,
  ].join('\n');

  return {
    json: {
      ...t,
      team,
      priority: ai.priority,
      sentiment: ai.sentiment,
      topic: ai.topic,
      customerRef: ai.customer_ref,
      summary: ai.summary,
      reason: ai.reason,
      route,
      assignee,
      // Urgent tickets also go to escalationEmail, if set.
      notifyTo: [assignee, urgent ? String(s.escalationEmail || '').trim() : '']
        .filter((a, n, all) => a && all.indexOf(a) === n).join(','),
      notifySubject,
      notifyBody,
      ackMessage,
      sendAck: route !== 'ignore' && !t.isReply && s.sendAcknowledgement !== false,
      ticketLabelId: s.ticketLabelId,
      slackChannel: s.slackChannel,
    },
    pairedItem: { item: i },
  };
});

